1	package sync
2	
3	import (
4		"context"
5		"crypto/rand"
6		"encoding/hex"
7		"encoding/json"
8		"fmt"
9		"io"
10		"os"
11		"path/filepath"
12	
13		"github.com/okf-memory/okf-agent-memory/pkg/vault"
14	)
15	
16	// VaultConfig stores local configuration for syncing an OKF bundle.
17	type VaultConfig struct {
18		VaultID   string `json:"vault_id"`
19		HubURL    string `json:"hub_url,omitempty"`
20		AuthToken string `json:"auth_token,omitempty"`
21	}
22	
23	const vaultConfigFileName = ".okf-vault.json"
24	
25	// ResolveHubURL returns the hub URL from flag, config, or default.
26	func ResolveHubURL(flagURL string, cfg *VaultConfig) string {
27		if flagURL != "" {
28			return flagURL
29		}
30		if cfg != nil && cfg.HubURL != "" {
31			return cfg.HubURL
32		}
33		return "http://127.0.0.1:8080"
34	}
35	
36	// ResolveToken returns the auth token from flag, env, config, or empty.
37	func ResolveToken(flagToken string, cfg *VaultConfig) string {
38		if flagToken != "" {
39			return flagToken
40		}
41		if env := os.Getenv("OKF_HUB_TOKEN"); env != "" {
42			return env
43		}
44		if cfg != nil && cfg.AuthToken != "" {
45			return cfg.AuthToken
46		}
47		return ""
48	}
49	
50	// LoadVaultConfig reads vault configuration from the bundle directory.
51	func LoadVaultConfig(dir string) (*VaultConfig, error) {
52		cfgPath := filepath.Join(dir, vaultConfigFileName)
53		// #nosec G304 -- cfgPath is within user bundle root
54		data, err := os.ReadFile(cfgPath)
55		if err != nil {
56			return nil, fmt.Errorf("failed to read %s: %w", cfgPath, err)
57		}
58		var cfg VaultConfig
59		if err := json.Unmarshal(data, &cfg); err != nil {
60			return nil, fmt.Errorf("failed to parse %s: %w", cfgPath, err)
61		}
62		return &cfg, nil
63	}
64	
65	// SaveVaultConfig writes vault configuration to the bundle directory.
66	func SaveVaultConfig(dir string, cfg *VaultConfig) error {
67		cfgPath := filepath.Join(dir, vaultConfigFileName)
68		// #nosec G117 -- local vault configuration optionally stores user hub bearer token
69		data, err := json.MarshalIndent(cfg, "", "  ")
70		if err != nil {
71			return err
72		}
73		// #nosec G703,G306 -- cfgPath is within user bundle root
74		return os.WriteFile(cfgPath, data, 0o644)
75	}
76	
77	// InitVault generates a new vault ID and secret key, saves config, and prints the emergency kit.
78	func InitVault(w io.Writer, dir, hubURL, authToken string) error {
79		idBytes := make([]byte, 16)
80		if _, err := rand.Read(idBytes); err != nil {
81			return fmt.Errorf("failed to generate random vault id: %w", err)
82		}
83		vaultID := "v_" + hex.EncodeToString(idBytes)
84	
85		secretKey, err := vault.GenerateSecretKey()
86		if err != nil {
87			return fmt.Errorf("failed to generate secret key: %w", err)
88		}
89	
90		if hubURL == "" {
91			hubURL = "http://127.0.0.1:8080"
92		}
93	
94		cfg := &VaultConfig{
95			VaultID:   vaultID,
96			HubURL:    hubURL,
97			AuthToken: authToken,
98		}
99		if err := SaveVaultConfig(dir, cfg); err != nil {
100			return fmt.Errorf("failed to save %s: %w", vaultConfigFileName, err)
101		}
102	
103		_, _ = fmt.Fprintf(w, `
104	================================================================================
105	                       OKF MEMORY HUB — EMERGENCY KIT
106	================================================================================
107	Vault ID:   %s
108	Secret Key: %s
109	
110	CRITICAL WARNING:
111	Your knowledge bundle is encrypted client-side using zero-knowledge AES-256-GCM.
112	If you lose your master password and this Secret Key, your data stored on the
113	Hub CANNOT be recovered by anyone. Store this Emergency Kit in a safe place.
114	================================================================================
115	`, vaultID, secretKey)
116	
117		return nil
118	}
119	
120	// HubOp configures a remote hub push, pull, or sync operation.
121	type HubOp struct {
122		Dir          string
123		Client       *Client
124		VaultID      string
125		Password     string
126		SecretKey    string
127		Message      string // used by HubPush and HubSync
128		AgentVersion string // used by HubPush and HubSync
129	}
130	
131	// HubPush pushes local changes to the remote hub.
132	func HubPush(w io.Writer, op HubOp) error {
133		vaultKey, err := vault.DeriveVaultKey(op.Password, op.SecretKey)
134		if err != nil {
135			return fmt.Errorf("failed to derive vault key: %w", err)
136		}
137	
138		engine := NewEngine(op.Client, op.VaultID, vaultKey, op.Dir)
139		hostname, _ := os.Hostname()
140		if hostname == "" {
141			hostname = "local-device"
142		}
143		author := vault.CommitAuthor{
144			ClientID: hostname,
145			Agent:    "okf-cli/" + op.AgentVersion,
146		}
147	
148		res, err := engine.Push(context.Background(), author, op.Message)
149		if err != nil {
150			return fmt.Errorf("push failed: %w", err)
151		}
152	
153		_, _ = fmt.Fprintf(w, "Push completed: commit %s (uploaded %d, unchanged %d)\n", res.CommitHash, res.UploadedBlobs, res.UnchangedBlobs)
154		return nil
155	}
156	
157	// HubPull pulls latest remote changes into the local bundle.
158	func HubPull(w io.Writer, op HubOp) error {
159		vaultKey, err := vault.DeriveVaultKey(op.Password, op.SecretKey)
160		if err != nil {
161			return fmt.Errorf("failed to derive vault key: %w", err)
162		}
163	
164		engine := NewEngine(op.Client, op.VaultID, vaultKey, op.Dir)
165		res, err := engine.Pull(context.Background())
166		if err != nil {
167			return fmt.Errorf("pull failed: %w", err)
168		}
169	
170		_, _ = fmt.Fprintf(w, "Pull completed: commit %s (updated %d, deleted %d)\n", res.CommitHash, len(res.UpdatedFiles), len(res.DeletedFiles))
171		return nil
172	}
173	
174	// HubSync performs a pull-then-push with automated conflict reconciliation.
175	func HubSync(w io.Writer, op HubOp) error {
176		vaultKey, err := vault.DeriveVaultKey(op.Password, op.SecretKey)
177		if err != nil {
178			return fmt.Errorf("failed to derive vault key: %w", err)
179		}
180	
181		engine := NewEngine(op.Client, op.VaultID, vaultKey, op.Dir)
182		hostname, _ := os.Hostname()
183		if hostname == "" {
184			hostname = "local-device"
185		}
186		author := vault.CommitAuthor{
187			ClientID: hostname,
188			Agent:    "okf-cli/" + op.AgentVersion,
189		}
190	
191		res, err := engine.Sync(context.Background(), author, op.Message)
192		if err != nil {
193			return fmt.Errorf("sync failed: %w", err)
194		}
195	
196		if len(res.Conflicts) > 0 {
197			for _, c := range res.Conflicts {
198				forked := ConflictForkPath(c.Path, c.LocalEntry)
199				_, _ = fmt.Fprintf(w, "⚠️  Collision detected at %s. Local version saved as %s.\n", c.Path, forked)
200			}
201		}
202	
203		_, _ = fmt.Fprintf(w, "Sync completed: commit %s\n", res.CommitHash)
204		return nil
205	}
