1	package sync
2	
3	import (
4		"context"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"strings"
10		"time"
11	
12		"github.com/okf-memory/okf-agent-memory/pkg/vault"
13	)
14	
15	// PushResult contains metadata about a successful push operation.
16	type PushResult struct {
17		CommitHash     string
18		UploadedBlobs  int
19		UnchangedBlobs int
20	}
21	
22	// PullResult contains details about files updated during a pull.
23	type PullResult struct {
24		CommitHash   string
25		UpdatedFiles []string
26		DeletedFiles []string
27	}
28	
29	// SyncResult contains the final commit hash and any detected conflicts.
30	type SyncResult struct {
31		CommitHash string
32		Conflicts  []Conflict
33	}
34	
35	// DefaultMaxSyncRetries is the maximum number of times Sync will retry on concurrent head conflicts (HTTP 409).
36	const DefaultMaxSyncRetries = 5
37	
38	// Engine coordinates bundle scanning, client-side encryption/decryption,
39	// and sync operations with the remote OKF Memory Hub.
40	type Engine struct {
41		Client     *Client
42		VaultID    string
43		VaultKey   []byte
44		BundlePath string
45		cachedTree *vault.Tree
46		cachedHead string
47	}
48	
49	// NewEngine initializes a synchronization engine for an OKF bundle.
50	func NewEngine(client *Client, vaultID string, vaultKey []byte, bundlePath string) *Engine {
51		engine := &Engine{
52			Client:     client,
53			VaultID:    vaultID,
54			VaultKey:   vaultKey,
55			BundlePath: bundlePath,
56			cachedTree: vault.NewTree(),
57		}
58		// Resume from the last synced position recorded inside the bundle (if any)
59		// so consecutive CLI invocations behave like one continuous session.
60		// Missing or invalid state is ignored; the engine then starts empty.
61		engine.loadState()
62		return engine
63	}
64	
65	// ScanBundle walks the local bundle directory and reads all non-hidden files into memory.
66	func (e *Engine) ScanBundle() (map[string][]byte, error) {
67		files := make(map[string][]byte)
68	
69		err := filepath.Walk(e.BundlePath, func(path string, info os.FileInfo, err error) error {
70			if err != nil {
71				return err
72			}
73			if info.IsDir() {
74				name := info.Name()
75				if strings.HasPrefix(name, ".") && name != "." {
76					return filepath.SkipDir
77				}
78				return nil
79			}
80	
81			name := info.Name()
82			if strings.HasPrefix(name, ".") || strings.HasSuffix(name, ".tmp") {
83				return nil
84			}
85	
86			relPath, err := filepath.Rel(e.BundlePath, path)
87			if err != nil {
88				return err
89			}
90			slashPath := filepath.ToSlash(relPath)
91	
92			// #nosec G122,G304 -- path is enumerated within validated bundle directory
93			data, err := os.ReadFile(path)
94			if err != nil {
95				return fmt.Errorf("sync: failed to read %s: %w", relPath, err)
96			}
97	
98			files[slashPath] = data
99			return nil
100		})
101		if err != nil {
102			return nil, fmt.Errorf("sync: bundle scan failed: %w", err)
103		}
104	
105		return files, nil
106	}
107	
108	// Push detects local bundle changes, encrypts modified files, uploads missing blobs,
109	// and atomically advances the remote vault head.
110	func (e *Engine) Push(ctx context.Context, author vault.CommitAuthor, message string) (*PushResult, error) {
111		files, err := e.ScanBundle()
112		if err != nil {
113			return nil, err
114		}
115	
116		newTree := vault.NewTree()
117		blobsToUpload := make(map[string][]byte)
118		var candidateHashes []string
119		unchangedCount := 0
120	
121		for path, content := range files {
122			plaintextHash := vault.HashPlaintext(content)
123	
124			// Change detection: Check if cached tree already has identical plaintext
125			if e.cachedTree != nil && !e.cachedTree.HasChanged(path, plaintextHash) {
126				entry := e.cachedTree.Entries[path]
127				newTree.Entries[path] = entry
128				unchangedCount++
129				continue
130			}
131	
132			// Encrypt file into binary envelope
133			envelopeBytes, err := vault.EncryptPayload(content, e.VaultKey)
134			if err != nil {
135				return nil, fmt.Errorf("sync: failed to encrypt %s: %w", path, err)
136			}
137	
138			blobHash := vault.HashBlob(envelopeBytes)
139			blobsToUpload[blobHash] = envelopeBytes
140			candidateHashes = append(candidateHashes, blobHash)
141	
142			newTree.Entries[path] = vault.TreeEntry{
143				BlobHash:      blobHash,
144				Size:          int64(len(content)),
145				PlaintextHash: plaintextHash,
146				ModifiedAt:    time.Now().UTC().Format(time.RFC3339),
147			}
148		}
149	
150		// 1. Upload missing content blobs
151		if len(candidateHashes) > 0 {
152			missing, err := e.Client.CheckMissingBlobs(ctx, e.VaultID, candidateHashes)
153			if err != nil {
154				return nil, fmt.Errorf("sync: check missing blobs failed: %w", err)
155			}
156			for _, h := range missing {
157				if data, ok := blobsToUpload[h]; ok {
158					if err := e.Client.PutBlob(ctx, e.VaultID, h, data); err != nil {
159						return nil, fmt.Errorf("sync: put blob %s failed: %w", h, err)
160					}
161				}
162			}
163		}
164	
165		// 2. Encrypt and upload Tree manifest
166		treeBytes, err := newTree.Serialize()
167		if err != nil {
168			return nil, fmt.Errorf("sync: tree serialization failed: %w", err)
169		}
170	
171		treeEnvelope, err := vault.EncryptPayload(treeBytes, e.VaultKey)
172		if err != nil {
173			return nil, fmt.Errorf("sync: tree encryption failed: %w", err)
174		}
175	
176		treeBlobHash := vault.HashBlob(treeEnvelope)
177		if err := e.Client.PutBlob(ctx, e.VaultID, treeBlobHash, treeEnvelope); err != nil {
178			return nil, fmt.Errorf("sync: put tree blob failed: %w", err)
179		}
180	
181		// 3. Create, encrypt, and upload Commit object
182		var expectedHead *string
183		if e.cachedHead != "" {
184			expectedHead = &e.cachedHead
185		}
186	
187		commit := vault.NewCommit(expectedHead, treeBlobHash, author, message)
188		commitBytes, err := commit.Serialize()
189		if err != nil {
190			return nil, fmt.Errorf("sync: commit serialization failed: %w", err)
191		}
192	
193		commitEnvelope, err := vault.EncryptPayload(commitBytes, e.VaultKey)
194		if err != nil {
195			return nil, fmt.Errorf("sync: commit encryption failed: %w", err)
196		}
197	
198		commitBlobHash := vault.HashBlob(commitEnvelope)
199		if err := e.Client.PutBlob(ctx, e.VaultID, commitBlobHash, commitEnvelope); err != nil {
200			return nil, fmt.Errorf("sync: put commit blob failed: %w", err)
201		}
202	
203		// 4. Atomically advance Head
204		resp, err := e.Client.Commit(ctx, e.VaultID, commitBlobHash, expectedHead)
205		if err != nil {
206			return nil, err
207		}
208	
209		e.cachedHead = resp.Head
210		e.cachedTree = newTree
211	
212		if err := e.saveState(); err != nil {
213			return nil, fmt.Errorf("sync: commit %s was accepted by the hub, but persisting the sync state failed: %w", resp.Head, err)
214		}
215	
216		return &PushResult{
217			CommitHash:     resp.Head,
218			UploadedBlobs:  len(blobsToUpload),
219			UnchangedBlobs: unchangedCount,
220		}, nil
221	}
222	
223	// Pull downloads the latest commit and tree manifest from the hub,
224	// downloads new blobs, decrypts them, and updates the local filesystem.
225	func (e *Engine) Pull(ctx context.Context) (*PullResult, error) {
226		headResp, err := e.Client.GetHead(ctx, e.VaultID)
227		if err != nil {
228			return nil, err
229		}
230	
231		if headResp.HeadCommit == "" {
232			return &PullResult{}, nil
233		}
234	
235		if headResp.HeadCommit == e.cachedHead {
236			return &PullResult{CommitHash: e.cachedHead}, nil
237		}
238	
239		// 1. Download and decrypt Commit
240		commitEnvelope, err := e.Client.GetBlob(ctx, e.VaultID, headResp.HeadCommit)
241		if err != nil {
242			return nil, fmt.Errorf("sync: failed to get commit blob %s: %w", headResp.HeadCommit, err)
243		}
244	
245		commitBytes, err := vault.DecryptPayload(commitEnvelope, e.VaultKey)
246		if err != nil {
247			return nil, fmt.Errorf("sync: failed to decrypt commit blob: %w", err)
248		}
249	
250		commit, err := vault.ParseCommit(commitBytes)
251		if err != nil {
252			return nil, fmt.Errorf("sync: failed to parse commit: %w", err)
253		}
254	
255		// 2. Download and decrypt Tree
256		treeEnvelope, err := e.Client.GetBlob(ctx, e.VaultID, commit.TreeHash)
257		if err != nil {
258			return nil, fmt.Errorf("sync: failed to get tree blob %s: %w", commit.TreeHash, err)
259		}
260	
261		treeBytes, err := vault.DecryptPayload(treeEnvelope, e.VaultKey)
262		if err != nil {
263			return nil, fmt.Errorf("sync: failed to decrypt tree blob: %w", err)
264		}
265	
266		remoteTree, err := vault.ParseTree(treeBytes)
267		if err != nil {
268			return nil, fmt.Errorf("sync: failed to parse tree: %w", err)
269		}
270		if err := validateTreePaths(remoteTree); err != nil {
271			return nil, fmt.Errorf("sync: refusing to pull commit %s: %w", headResp.HeadCommit, err)
272		}
273	
274		// 3. Diff and update local filesystem
275		diff := vault.DiffTrees(e.cachedTree, remoteTree)
276	
277		var updated []string
278		toFetch := append(diff.Added, diff.Modified...)
279		writeTargets, deleteTargets, err := e.hubTargets(toFetch, diff.Deleted)
280		if err != nil {
281			return nil, fmt.Errorf("sync: refusing to pull commit %s: %w", headResp.HeadCommit, err)
282		}
283		for _, path := range toFetch {
284			entry := remoteTree.Entries[path]
285			blobBytes, err := e.Client.GetBlob(ctx, e.VaultID, entry.BlobHash)
286			if err != nil {
287				return nil, fmt.Errorf("sync: failed to get blob %s for %s: %w", entry.BlobHash, path, err)
288			}
289	
290			plainBytes, err := vault.DecryptPayload(blobBytes, e.VaultKey)
291			if err != nil {
292				return nil, fmt.Errorf("sync: failed to decrypt %s: %w", path, err)
293			}
294	
295			fullPath := writeTargets[path]
296			if err := os.MkdirAll(filepath.Dir(fullPath), 0o755); err != nil {
297				return nil, fmt.Errorf("sync: failed to mkdir for %s: %w", path, err)
298			}
299	
300			if err := os.WriteFile(fullPath, plainBytes, 0o644); err != nil {
301				return nil, fmt.Errorf("sync: failed to write %s: %w", path, err)
302			}
303			updated = append(updated, path)
304		}
305	
306		for _, path := range diff.Deleted {
307			_ = os.Remove(deleteTargets[path])
308		}
309	
310		e.cachedHead = headResp.HeadCommit
311		e.cachedTree = remoteTree
312	
313		if err := e.saveState(); err != nil {
314			return nil, fmt.Errorf("sync: pulled commit %s, but persisting the sync state failed: %w", headResp.HeadCommit, err)
315		}
316	
317		return &PullResult{
318			CommitHash:   headResp.HeadCommit,
319			UpdatedFiles: updated,
320			DeletedFiles: diff.Deleted,
321		}, nil
322	}
323	
324	// Sync performs a full synchronization cycle:
325	// Attempts Push; if an HTTP 409 conflict occurs, it reconciles the divergent trees,
326	// writes local conflict files if necessary, and pushes the merged commit.
327	func (e *Engine) Sync(ctx context.Context, author vault.CommitAuthor, message string) (*SyncResult, error) {
328		pushRes, err := e.Push(ctx, author, message)
329		if err == nil {
330			return &SyncResult{
331				CommitHash: pushRes.CommitHash,
332			}, nil
333		}
334	
335		var conflictErr *HeadConflictError
336		if !errors.As(err, &conflictErr) {
337			return nil, err
338		}
339	
340		remoteHead := conflictErr.CurrentHead
341	
342		for attempt := 0; attempt < DefaultMaxSyncRetries; attempt++ {
343			if attempt > 0 {
344				backoff := time.Duration(10*(1<<attempt)) * time.Millisecond
345				select {
346				case <-time.After(backoff):
347				case <-ctx.Done():
348					return nil, ctx.Err()
349				}
350			}
351	
352			// 409 Conflict encountered: Fetch remote state
353			remoteCommitBlob, err := e.Client.GetBlob(ctx, e.VaultID, remoteHead)
354			if err != nil {
355				return nil, fmt.Errorf("sync: failed to fetch remote conflict head %s: %w", remoteHead, err)
356			}
357	
358			remoteCommitBytes, err := vault.DecryptPayload(remoteCommitBlob, e.VaultKey)
359			if err != nil {
360				return nil, fmt.Errorf("sync: failed to decrypt remote commit: %w", err)
361			}
362	
363			remoteCommit, err := vault.ParseCommit(remoteCommitBytes)
364			if err != nil {
365				return nil, fmt.Errorf("sync: failed to parse remote commit: %w", err)
366			}
367	
368			remoteTreeBlob, err := e.Client.GetBlob(ctx, e.VaultID, remoteCommit.TreeHash)
369			if err != nil {
370				return nil, fmt.Errorf("sync: failed to fetch remote tree: %w", err)
371			}
372	
373			remoteTreeBytes, err := vault.DecryptPayload(remoteTreeBlob, e.VaultKey)
374			if err != nil {
375				return nil, fmt.Errorf("sync: failed to decrypt remote tree: %w", err)
376			}
377	
378			remoteTree, err := vault.ParseTree(remoteTreeBytes)
379			if err != nil {
380				return nil, fmt.Errorf("sync: failed to parse remote tree: %w", err)
381			}
382			if err := validateTreePaths(remoteTree); err != nil {
383				return nil, fmt.Errorf("sync: refusing to reconcile with remote commit %s: %w", remoteHead, err)
384			}
385	
386			// Construct current local tree from files on disk
387			localFiles, err := e.ScanBundle()
388			if err != nil {
389				return nil, err
390			}
391	
392			localTree := vault.NewTree()
393			blobsToUpload := make(map[string][]byte)
394			var candidateHashes []string
395	
396			for path, content := range localFiles {
397				plainHash := vault.HashPlaintext(content)
398				envelopeBytes, err := vault.EncryptPayload(content, e.VaultKey)
399				if err != nil {
400					return nil, err
401				}
402				blobHash := vault.HashBlob(envelopeBytes)
403				blobsToUpload[blobHash] = envelopeBytes
404				candidateHashes = append(candidateHashes, blobHash)
405	
406				localTree.Entries[path] = vault.TreeEntry{
407					BlobHash:      blobHash,
408					Size:          int64(len(content)),
409					PlaintextHash: plainHash,
410					ModifiedAt:    time.Now().UTC().Format(time.RFC3339),
411				}
412			}
413	
414			// Reconcile base, local, and remote
415			reconcileRes, err := Reconcile(e.cachedTree, localTree, remoteTree)
416			if err != nil {
417				return nil, fmt.Errorf("sync: reconciliation failed: %w", err)
418			}
419	
420			// Auto-merge bookkeeping files: append-only log.md and per-listing index.md
421			var unresolvedConflicts []Conflict
422			for _, c := range reconcileRes.Conflicts {
423				if c.LocalEntry.BlobHash != "" && c.RemoteEntry.BlobHash != "" {
424					if mergedPlain, ok := e.mergeBookkeeping(ctx, c, localFiles[c.Path]); ok {
425						mergedEnv, err := vault.EncryptPayload(mergedPlain, e.VaultKey)
426						if err == nil {
427							mergedBlobHash := vault.HashBlob(mergedEnv)
428							blobsToUpload[mergedBlobHash] = mergedEnv
429							candidateHashes = append(candidateHashes, mergedBlobHash)
430							localFiles[c.Path] = mergedPlain
431	
432							reconcileRes.MergedTree.Entries[c.Path] = vault.TreeEntry{
433								BlobHash:      mergedBlobHash,
434								Size:          int64(len(mergedPlain)),
435								PlaintextHash: vault.HashPlaintext(mergedPlain),
436								ModifiedAt:    time.Now().UTC().Format(time.RFC3339),
437							}
438							continue
439						}
440					}
441				}
442				unresolvedConflicts = append(unresolvedConflicts, c)
443			}
444			reconcileRes.Conflicts = unresolvedConflicts
445	
446			if len(reconcileRes.Conflicts) > 0 {
447				ApplyConflictFailsafe(reconcileRes.MergedTree, reconcileRes.Conflicts)
448			}
449	
450			// Update local files with remote changes and conflict files
451			diff := vault.DiffTrees(localTree, reconcileRes.MergedTree)
452			toFetch := append(diff.Added, diff.Modified...)
453			writeTargets, deleteTargets, err := e.hubTargets(toFetch, diff.Deleted)
454			if err != nil {
455				return nil, fmt.Errorf("sync: refusing to reconcile with remote commit %s: %w", remoteHead, err)
456			}
457			for _, path := range toFetch {
458				entry := reconcileRes.MergedTree.Entries[path]
459				var plainBytes []byte
460				if localData, ok := localFiles[path]; ok && vault.HashPlaintext(localData) == entry.PlaintextHash {
461					plainBytes = localData
462				} else if envelopeData, ok := blobsToUpload[entry.BlobHash]; ok {
463					var err error
464					plainBytes, err = vault.DecryptPayload(envelopeData, e.VaultKey)
465					if err != nil {
466						return nil, fmt.Errorf("sync: failed to decrypt local blob for %s: %w", path, err)
467					}
468				} else {
469					blobBytes, err := e.Client.GetBlob(ctx, e.VaultID, entry.BlobHash)
470					if err != nil {
471						return nil, fmt.Errorf("sync: failed to fetch blob %s for %s: %w", entry.BlobHash, path, err)
472					}
473					plainBytes, err = vault.DecryptPayload(blobBytes, e.VaultKey)
474					if err != nil {
475						return nil, fmt.Errorf("sync: failed to decrypt %s: %w", path, err)
476					}
477				}
478	
479				fullPath := writeTargets[path]
480				_ = os.MkdirAll(filepath.Dir(fullPath), 0o755)
481				_ = os.WriteFile(fullPath, plainBytes, 0o644)
482			}
483	
484			for _, path := range diff.Deleted {
485				_ = os.Remove(deleteTargets[path])
486			}
487	
488			// Upload new blobs
489			if len(candidateHashes) > 0 {
490				missing, err := e.Client.CheckMissingBlobs(ctx, e.VaultID, candidateHashes)
491				if err == nil {
492					for _, h := range missing {
493						if d, ok := blobsToUpload[h]; ok {
494							_ = e.Client.PutBlob(ctx, e.VaultID, h, d)
495						}
496					}
497				}
498			}
499	
500			// Upload merged tree
501			mergedTreeBytes, _ := reconcileRes.MergedTree.Serialize()
502			mergedTreeEnv, _ := vault.EncryptPayload(mergedTreeBytes, e.VaultKey)
503			mergedTreeHash := vault.HashBlob(mergedTreeEnv)
504			_ = e.Client.PutBlob(ctx, e.VaultID, mergedTreeHash, mergedTreeEnv)
505	
506			// Create merge commit pointing to remoteHead
507			mergeCommit := vault.NewCommit(&remoteHead, mergedTreeHash, author, "Reconcile merge: "+message)
508			mergeCommitBytes, _ := mergeCommit.Serialize()
509			mergeCommitEnv, _ := vault.EncryptPayload(mergeCommitBytes, e.VaultKey)
510			mergeCommitHash := vault.HashBlob(mergeCommitEnv)
511			_ = e.Client.PutBlob(ctx, e.VaultID, mergeCommitHash, mergeCommitEnv)
512	
513			resp, err := e.Client.Commit(ctx, e.VaultID, mergeCommitHash, &remoteHead)
514			if err != nil {
515				var raceErr *HeadConflictError
516				if errors.As(err, &raceErr) {
517					// Server head advanced during reconciliation, retry with new head
518					remoteHead = raceErr.CurrentHead
519					e.cachedTree = remoteTree
520					continue
521				}
522				return nil, fmt.Errorf("sync: failed to commit merged head: %w", err)
523			}
524	
525			e.cachedHead = resp.Head
526			e.cachedTree = reconcileRes.MergedTree
527	
528			if err := e.saveState(); err != nil {
529				return nil, fmt.Errorf("sync: merged commit %s was accepted by the hub, but persisting the sync state failed: %w", resp.Head, err)
530			}
531	
532			return &SyncResult{
533				CommitHash: resp.Head,
534				Conflicts:  reconcileRes.Conflicts,
535			}, nil
536		}
537	
538		return nil, fmt.Errorf("sync: exceeded maximum reconciliation retries (%d)", DefaultMaxSyncRetries)
539	}
540	
541	// fetchPlaintext downloads and decrypts a blob from the hub.
542	func (e *Engine) fetchPlaintext(ctx context.Context, blobHash string) ([]byte, error) {
543		envelope, err := e.Client.GetBlob(ctx, e.VaultID, blobHash)
544		if err != nil {
545			return nil, err
546		}
547		return vault.DecryptPayload(envelope, e.VaultKey)
548	}
549	
550	// mergeBookkeeping resolves a collision on a bookkeeping file that has a
551	// semantic merge: log.md (union of entries) or index.md (3-way merge per
552	// listing). It returns ok=false for any other file, or when the merge cannot
553	// be done safely, so the caller falls back to the collision failsafe.
554	func (e *Engine) mergeBookkeeping(ctx context.Context, c Conflict, localPlain []byte) ([]byte, bool) {
555		switch {
556		case isLogFile(c.Path):
557			remotePlain, err := e.fetchPlaintext(ctx, c.RemoteEntry.BlobHash)
558			if err != nil {
559				return nil, false
560			}
561			merged, err := MergeLogContent(localPlain, remotePlain)
562			return merged, err == nil
563	
564		case isIndexFile(c.Path):
565			remotePlain, err := e.fetchPlaintext(ctx, c.RemoteEntry.BlobHash)
566			if err != nil {
567				return nil, false
568			}
569			var basePlain []byte
570			if c.BaseEntry != nil && c.BaseEntry.BlobHash != "" {
571				if basePlain, err = e.fetchPlaintext(ctx, c.BaseEntry.BlobHash); err != nil {
572					return nil, false
573				}
574			}
575			return MergeIndexContent(basePlain, localPlain, remotePlain)
576		}
577		return nil, false
578	}
579	
580	func isLogFile(path string) bool {
581		clean := filepath.ToSlash(filepath.Clean(path))
582		return clean == "log.md" || strings.HasSuffix(clean, "/log.md")
583	}
