1	package sync
2	
3	import (
4		"path/filepath"
5		"sort"
6		"strings"
7	
8		"github.com/okf-memory/okf-agent-memory/pkg/vault"
9	)
10	
11	// Conflict describes a collision where the same file was modified incompatibly in local and remote.
12	type Conflict struct {
13		Path        string
14		BaseEntry   *vault.TreeEntry // nil if the file was newly created in both branches
15		LocalEntry  vault.TreeEntry
16		RemoteEntry vault.TreeEntry
17	}
18	
19	// ReconcileResult contains the computed merged tree and any detected conflicts.
20	type ReconcileResult struct {
21		MergedTree *vault.Tree
22		Conflicts  []Conflict
23	}
24	
25	// ConflictLocalPath computes the fork filename for saving conflicting local changes.
26	// e.g. "ideas.md" -> "ideas.conflict-local.md"
27	func ConflictLocalPath(path string) string {
28		ext := filepath.Ext(path)
29		if ext != "" {
30			base := strings.TrimSuffix(path, ext)
31			return base + ".conflict-local" + ext
32		}
33		return path + ".conflict-local"
34	}
35	
36	// ConflictForkPath computes the fork filename for saving conflicting local
37	// changes, suffixed with a short hash of the local content's plaintext hash.
38	// The suffix keeps every conflicting writer's fork distinct: with one fixed
39	// path per file, a later device's conflict would overwrite the conflict copy a
40	// previous device already committed, silently dropping that device's edit from
41	// the current tree. The plaintext hash (not the blob hash) is used because the
42	// encrypted envelope is non-deterministic across devices. The fixed-path
43	// result of ConflictLocalPath is returned when no plaintext hash is available.
44	// e.g. "ideas.md" -> "ideas.conflict-local-1a2b3c4d.md"
45	func ConflictForkPath(path string, local vault.TreeEntry) string {
46		base := ConflictLocalPath(path)
47		hash := local.PlaintextHash
48		if hash == "" {
49			return base
50		}
51		if len(hash) > 8 {
52			hash = hash[:8]
53		}
54		ext := filepath.Ext(base)
55		if ext != "" {
56			return strings.TrimSuffix(base, ext) + "-" + hash + ext
57		}
58		return base + "-" + hash
59	}
60	
61	// Reconcile performs a 3-way merge of the file manifests: base, local, and remote.
62	// If both local and remote modified disjoint sets of files, it merges cleanly with 0 conflicts.
63	// If both modified the same file incompatibly, it reports a Conflict.
64	func Reconcile(base, local, remote *vault.Tree) (*ReconcileResult, error) {
65		if base == nil {
66			base = vault.NewTree()
67		}
68		if local == nil {
69			local = vault.NewTree()
70		}
71		if remote == nil {
72			remote = vault.NewTree()
73		}
74	
75		merged := vault.NewTree()
76		var conflicts []Conflict
77	
78		// Collect all unique paths
79		allPathsMap := make(map[string]struct{})
80		for p := range base.Entries {
81			allPathsMap[p] = struct{}{}
82		}
83		for p := range local.Entries {
84			allPathsMap[p] = struct{}{}
85		}
86		for p := range remote.Entries {
87			allPathsMap[p] = struct{}{}
88		}
89	
90		var allPaths []string
91		for p := range allPathsMap {
92			allPaths = append(allPaths, p)
93		}
94		sort.Strings(allPaths)
95	
96		for _, path := range allPaths {
97			baseEntry, inBase := base.Entries[path]
98			localEntry, inLocal := local.Entries[path]
99			remoteEntry, inRemote := remote.Entries[path]
100	
101			// 1. Unchanged anywhere
102			if inBase && inLocal && inRemote &&
103				baseEntry.PlaintextHash == localEntry.PlaintextHash &&
104				baseEntry.PlaintextHash == remoteEntry.PlaintextHash {
105				merged.Entries[path] = localEntry
106				continue
107			}
108	
109			// 2. Added only in Local
110			if !inBase && inLocal && !inRemote {
111				merged.Entries[path] = localEntry
112				continue
113			}
114	
115			// 3. Added only in Remote
116			if !inBase && !inLocal && inRemote {
117				merged.Entries[path] = remoteEntry
118				continue
119			}
120	
121			// 4. Deleted only in Local (unchanged in Remote)
122			if inBase && !inLocal && inRemote && baseEntry.PlaintextHash == remoteEntry.PlaintextHash {
123				// Deleted, omit from merged
124				continue
125			}
126	
127			// 5. Deleted only in Remote (unchanged in Local)
128			if inBase && inLocal && !inRemote && baseEntry.PlaintextHash == localEntry.PlaintextHash {
129				// Deleted, omit from merged
130				continue
131			}
132	
133			// 6. Modified only in Local (unchanged in Remote)
134			if inBase && inLocal && inRemote &&
135				baseEntry.PlaintextHash != localEntry.PlaintextHash &&
136				baseEntry.PlaintextHash == remoteEntry.PlaintextHash {
137				merged.Entries[path] = localEntry
138				continue
139			}
140	
141			// 7. Modified only in Remote (unchanged in Local)
142			if inBase && inLocal && inRemote &&
143				baseEntry.PlaintextHash == localEntry.PlaintextHash &&
144				baseEntry.PlaintextHash != remoteEntry.PlaintextHash {
145				merged.Entries[path] = remoteEntry
146				continue
147			}
148	
149			// 8. Both modified or added
150			if inLocal && inRemote {
151				if localEntry.PlaintextHash == remoteEntry.PlaintextHash {
152					// Both made identical change
153					merged.Entries[path] = localEntry
154					continue
155				}
156	
157				// Incompatible modification collision!
158				var basePtr *vault.TreeEntry
159				if inBase {
160					basePtr = &baseEntry
161				}
162				conflicts = append(conflicts, Conflict{
163					Path:        path,
164					BaseEntry:   basePtr,
165					LocalEntry:  localEntry,
166					RemoteEntry: remoteEntry,
167				})
168				// Place remote version in merged by default
169				merged.Entries[path] = remoteEntry
170				continue
171			}
172	
173			// 9. Deleted in one, modified in the other -> conflict
174			var basePtr *vault.TreeEntry
175			if inBase {
176				basePtr = &baseEntry
177			}
178			conflicts = append(conflicts, Conflict{
179				Path:        path,
180				BaseEntry:   basePtr,
181				LocalEntry:  localEntry,
182				RemoteEntry: remoteEntry,
183			})
184			if inRemote {
185				merged.Entries[path] = remoteEntry
186			} else if inLocal {
187				merged.Entries[path] = localEntry
188			}
189		}
190	
191		return &ReconcileResult{
192			MergedTree: merged,
193			Conflicts:  conflicts,
194		}, nil
195	}
196	
197	// ApplyConflictFailsafe updates mergedTree according to the CLI collision policy:
198	// The remote version is adopted at path, and the local version is preserved at ConflictLocalPath(path).
199	func ApplyConflictFailsafe(merged *vault.Tree, conflicts []Conflict) {
200		if merged == nil {
201			return
202		}
203		for _, c := range conflicts {
204			forked := ConflictForkPath(c.Path, c.LocalEntry)
205			if c.RemoteEntry.BlobHash != "" {
206				merged.Entries[c.Path] = c.RemoteEntry
207			}
208			if c.LocalEntry.BlobHash != "" {
209				merged.Entries[forked] = c.LocalEntry
210			}
211		}
212	}
